# Code generated by Claude
"""
Tests of src/control_loop.py without a window (viewer=None).

    python experiments/cc_loop_tests.py headless [--no-cameras]   # the manual bench scenario headless; writes a CSV
    python experiments/cc_loop_tests.py hold                      # the hold rule with exclusivity on, and the control run
    python experiments/cc_loop_tests.py neck                      # the neck: default aim, slew limit, exempt from exclusivity

headless: the same scripted keys as experiments/cc_bench_scenarios.sh manual, through the keyboard source, with the
cameras rendered over an EGL offscreen context (or skipped). The CSV is compared with the pre-refactor baseline by
experiments/cc_bench_compare.py; the tick rate is printed.

hold: a scripted source commands the base, then (while the base is still moving) the arms. With cfg["exclusive"] the arms
command must wait until the base has settled, the wait must be logged, and a newer arms command that arrives during the
wait must replace the older one. The control run (exclusive off) applies the arms command at once.
"""

import os
import sys
import time
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))
if not os.environ.get("DISPLAY"):
    os.environ.setdefault("MUJOCO_GL", "egl")          # headless: offscreen cameras through EGL

import mujoco  # noqa: E402
import numpy as np  # noqa: E402

from src import robot_specs  # noqa: E402
from src.control_loop import run_loop  # noqa: E402
from src.keyboard_source import DRIVE_CFG, key_code, make_keyboard_source  # noqa: E402
from src.simulator import RobotSimulator  # noqa: E402

SCENE = "models/scenes/chemistry_lab_combined.xml"
SPAWN = [-1.0, 3.5, 0.22]
TICK_HZ = 150.0         # the command tick (5 physics steps)
K = 2.4                 # ticks per old (62.5 Hz) tick: the scripts below were written in old ticks


def n(old_ticks):
    """The same instant as `old_ticks` old ticks, in ticks of the current rate."""
    return int(round(old_ticks * K))

MANUAL_KEYS = "12-108:UP,108-228:SPACE,240-336:LEFT,336-456:SPACE,480-624:PAGE_DOWN,648-792:PAGE_UP,816-888:3,936-1008:E,1032-1128:A,1152-1188:8,1200-1248:I"      # the tick numbers of experiments/cc_bench_scenarios.sh manual


def load(cameras):
    sim = RobotSimulator(model_path=str(PROJECT_ROOT / SCENE), cameras=robot_specs.CAMERA_SPECS if cameras else None,
                         pedestal_lift=robot_specs.PEDESTAL_SPECS)
    scale = float(os.environ.get("CC_NECK_MASS_SCALE", "1"))
    if scale != 1.0:                                  # experiment: how much of a difference is the neck's mass?
        for b in range(sim.model.nbody):
            if sim.model.body(b).name.startswith(robot_specs.NECK_SPECS["prefix"]):
                sim.model.body_mass[b] *= scale
                sim.model.body_inertia[b] *= scale
        mujoco.mj_setConst(sim.model, sim.data)
        print(f"NECK MASS SCALED by {scale}: neck mass now {sum(sim.model.body_mass[b] for b in range(sim.model.nbody) if sim.model.body(b).name.startswith('neck_')):.6f} kg")
    return sim.model, sim.data


def injected_keys(spec):
    inj = set()
    for tok in spec.split(","):
        fr, kname = tok.split(":", 1)
        lo, _, hi = fr.partition("-")
        for f in range(int(lo), int(hi or lo) + 1):
            inj.add((f, key_code(kname)))
    return inj


def steps_per_frame(model):
    return max(1, round(1.0 / model.opt.timestep / TICK_HZ))


def headless(cameras, out_csv):
    model, data = load(cameras)
    tick = [0]
    inj = injected_keys(MANUAL_KEYS)
    held = lambda code: (tick[0], code) in inj
    ped = mujoco.mj_name2id(model, mujoco.mjtObj.mjOBJ_ACTUATOR, robot_specs.PEDESTAL_SPECS["actuator_name"])
    spf = steps_per_frame(model)
    ped_step = robot_specs.PEDESTAL_SPECS["jog_speed"] * spf * model.opt.timestep
    kb = make_keyboard_source(model, held, DRIVE_CFG, ped_step, tuple(model.actuator_ctrlrange[ped]))
    cfg = {"source_hz": 1.0 / model.opt.timestep / spf, "spawn_pos": SPAWN, "held": held, "tick_ref": tick, "cameras": cameras,
           "bench_frames": n(520), "bench_log": out_csv}
    t0 = time.perf_counter()
    res = run_loop(model, data, {"keyboard": kb}, cfg, viewer=None)
    wall = time.perf_counter() - t0
    print(f"headless, cameras {'on (EGL, round robin)' if cameras else 'off'}: {res['frames']} ticks, {data.time:.1f} s of sim in "
          f"{wall:.1f} s wall (including the 1.4 s settle) = {data.time / wall:.2f}x real time; {res['frames'] / wall:.1f} ticks/s")


class Scripted:
    """A source driven by a function of the tick number; records what the loop shows it."""

    def __init__(self, fn, name="script"):
        self.fn, self.name, self.rec = fn, name, []

    def step(self, obs):
        base_speed = float(np.hypot(*obs["joint_velocities"][0:2]))
        self.rec.append((obs["tick"], obs["time"], base_speed, obs["applied"]["arm_targets"]["left"][2], obs["applied"]["twist"][0]))
        return self.fn(obs["tick"])

    def as_source(self):
        return {"name": self.name, "step": self.step}


def hold_test(exclusive):
    model, data = load(False)
    tick = [0]

    def script(k):
        if n(20) <= k < n(80):
            return {"mode": "base", "twist": (0.8, 0.0)}                    # the base drives at 0.8 m/s
        if n(80) <= k < n(90):
            return {"mode": "arms", "arm_targets": {"left": [0, 0, 0.6, 0, 0, 0, 0]}}      # while the base is still moving
        if n(90) <= k < n(100):
            return {"mode": "arms", "arm_targets": {"left": [0, 0, 0.9, 0, 0, 0, 0]}}      # a newer arms command replaces it
        return None
    sc = Scripted(script)
    spf = steps_per_frame(model)
    cfg = {"source_hz": 1.0 / model.opt.timestep / spf, "spawn_pos": SPAWN, "tick_ref": tick, "cameras": False,
           "exclusive": exclusive, "routes": {k: "script" for k in ("base", "pedestal", "arms.left", "arms.right", "gripper.left", "gripper.right")},
           "bench_frames": n(190)}
    res = run_loop(model, data, {"script": sc.as_source()}, cfg, viewer=None)
    rec = np.array(sc.rec)
    tgt = rec[:, 3]
    first = int(np.argmax(tgt > 1e-9)) if (tgt > 1e-9).any() else None
    print(f"\n=== hold test, exclusive={exclusive} ===")
    print(f"arms command first issued at tick {n(80)} (base moving at {rec[n(80) - 1, 2]:.2f} m/s)")
    if first is None:
        print("  the arm target never changed")
        return
    print(f"  arm target first applied at tick {first} (t={rec[first, 1]:.2f} s), i.e. {first - n(80)} ticks = {rec[first, 1] - rec[n(80), 1]:.2f} s after it was issued")
    print(f"  base speed when it was applied: {rec[first, 2]:.4f} m/s (base speed at tick {n(80)}: {rec[n(80), 2]:.3f}); applied twist before: {rec[first - 1, 4]:.4f} m/s")
    print(f"  arm joint-3 target applied: {tgt[first]:.3f} (the older command asked 0.6, the newer 0.9)")
    print(f"  hold log: {res['hold_log'] or 'none'}")
    return res, rec, first


def neck_test():
    from src.neck import neck_ids
    model, data = load(False)
    ids = neck_ids(model, robot_specs.NECK_SPECS)
    tick = [0]
    pan = ids["names"].index("shoulder_pan")
    home = np.array(robot_specs.NECK_SPECS["drive_pose"])

    def script(k):
        cmds = []
        if n(20) <= k < n(100):
            cmds.append({"mode": "base", "twist": (0.8, 0.0)})
        if n(40) <= k < n(60):
            cmds.append({"mode": "arms", "arm_targets": {"left": [0, 0, 0.6, 0, 0, 0, 0]}})       # waits for the base (exclusive)
        if n(30) <= k < n(40):
            cmds.append({"mode": "neck", "neck_targets": {"shoulder_pan": 0.6, "wrist_flex": -0.3}})   # while the base is moving
        return cmds
    rows = []

    class Rec(Scripted):
        def step(self, obs):
            q = np.array([obs["joint_angles"][a] for a in ids["qadr"]])
            rows.append((obs["tick"], obs["time"], q, np.array([obs["applied"]["neck_targets"][n] for n in ids["names"]]),
                         float(np.hypot(*obs["joint_velocities"][0:2])), obs["applied"]["arm_targets"]["left"][2]))
            return self.fn(obs["tick"])
    sc = Rec(script)
    spf = steps_per_frame(model)
    cfg = {"source_hz": 1.0 / model.opt.timestep / spf, "spawn_pos": SPAWN, "tick_ref": tick, "cameras": False, "exclusive": True,
           "routes": {k: "script" for k in ("base", "pedestal", "arms.left", "arms.right", "gripper.left", "gripper.right", "neck")},
           "bench_frames": n(190)}
    res = run_loop(model, data, {"script": sc.as_source()}, cfg, viewer=None)
    t = np.array([r[1] for r in rows]); Q = np.array([r[2] for r in rows]); T = np.array([r[3] for r in rows])
    base_speed = np.array([r[4] for r in rows]); arm_t = np.array([r[5] for r in rows])
    print("\n=== neck test ===")
    print(f"idle neck (ticks 0-{n(20) - 1}): drive pose {np.degrees(home).round(2)} deg; max |position - drive pose| = {np.degrees(np.abs(Q[:n(20)] - home).max()):.3f} deg; max |target - drive pose| = {np.abs(T[:n(20)] - home).max():.1e} rad")
    dt = float(np.diff(t).mean())
    step_max = np.abs(np.diff(T, axis=0)).max()
    print(f"slew limit: largest per-tick target change {step_max:.4f} rad = {step_max / dt:.2f} rad/s (limit {robot_specs.NECK_SPECS['max_speed']} rad/s)")
    i_neck = int(np.argmax(np.abs(T[:, pan] - home[pan]) > 1e-6))
    print(f"neck command sent at tick {n(30)} (base moving at {base_speed[n(30)]:.2f} m/s, arms command waiting since tick {n(40)}): neck target started moving at tick {i_neck}")
    print(f"  at tick {n(50)} (arms command still held, base speed {base_speed[n(50)]:.2f} m/s): neck pan target {np.degrees(T[n(50), pan]):.1f} deg, position {np.degrees(Q[n(50), pan]):.1f} deg; left joint-3 arm target {arm_t[n(50)]:.2f} (unchanged = held)")
    print(f"  final neck position (deg): {np.degrees(Q[-1]).round(1)} (commanded pan 34.4, wrist -17.2); hold log: {[ (round(h['t_start'],2), round(h['duration'],2)) for h in res['hold_log']]}")


if __name__ == "__main__":
    which = sys.argv[1] if len(sys.argv) > 1 else "headless"
    if which == "headless":
        cams = "--no-cameras" not in sys.argv
        headless(cams, f"data/cc_baseline/manual_headless_{'cams' if cams else 'nocams'}.csv")
    elif which == "hold":
        hold_test(True)
        hold_test(False)
    elif which == "neck":
        neck_test()
